import { Injectable } from '@nestjs/common';
import { ClickHouseClient, createClient } from '@clickhouse/client';

// Table (created via migration, shown here for reference):
//
// CREATE TABLE ad_click_counts
// (
//   adId        String,
//   windowStart DateTime,
//   count       UInt64,
//   version     UInt64
// )
// ENGINE = ReplacingMergeTree(version)
// ORDER BY (adId, windowStart);

@Injectable()
export class AdClickAggregatorService {
  private readonly client: ClickHouseClient;

  constructor() {
    this.client = createClient({ url: process.env.CLICKHOUSE_URL });
  }

  /**
   * Records a single ad click. Invoked once per incoming click event from
   * the ingestion pipeline — for a viral ad this can be thousands per second.
   */
  async recordClick(adId: string): Promise<void> {
    const windowStart = this.floorToMinute(new Date());
    const version = Date.now();

    // One row in, one INSERT out — on every single click, no accumulation.
    await this.client.insert({
      table: 'ad_click_counts',
      values: [
        {
          adId,
          windowStart: this.formatDateTime(windowStart),
          count: 1,
          version,
        },
      ],
      format: 'JSONEachRow',
    });
  }

  /**
   * Read path hit directly by the live advertiser dashboard on every refresh.
   */
  async getCount(adId: string, windowStart: Date): Promise<number> {
    const result = await this.client.query({
      query: `
        SELECT sum(count) AS total
        FROM ad_click_counts FINAL
        WHERE adId = {adId: String}
          AND windowStart = {windowStart: DateTime}
      `,
      query_params: {
        adId,
        windowStart: this.formatDateTime(windowStart),
      },
      format: 'JSONEachRow',
    });

    const rows = await result.json<{ total: string }>();
    return rows.length > 0 ? Number(rows[0].total) : 0;
  }

  private floorToMinute(date: Date): Date {
    const ms = date.getTime();
    return new Date(ms - (ms % 60_000));
  }

  private formatDateTime(date: Date): string {
    return date.toISOString().slice(0, 19).replace('T', ' ');
  }
}
